var t=`0407-cawl`;var i=`world-0407`;var a=`GB`;var r=`northern-europe`;var o=4;var s=110;var l={en:`Cawl`,ua:`Валлійський каул`};var g={en:`A traditional dish from United Kingdom, centered on lamb, yellow onion, carrot, turnip. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Велика Британія. Основні складники: ягнятина, жовта цибуля, морква, ріпа. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`lamb`,700,`g`],[`yellow-onion`,180,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 95 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 95 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:95,i:[[`water`,1500,`ml`],[`carrot`,240,`g`],[`turnip`,240,`g`],[`leek`,180,`g`],[`potato`,650,`g`],[`thyme`,3,`sprig`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,20,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var u={slug:t,id:i,country:`GB`,region:r,servings:4,minutes:110,title:l,text:g,steps:d};export{a as country,u as default,i as id,s as minutes,r as region,o as servings,t as slug,d as steps,g as text,l as title};